self.addEventListener("push",t=>{if(t.data)try{let i=t.data.json(),n={body:i.body||i.message||"",icon:i.icon||"/icons/icon-192x192.png",badge:i.badge||"/icons/icon-192x192.png",data:i.data||i.payload||{}};t.waitUntil(self.registration.showNotification(i.title||"New Notification",n))}catch{let i=t.data.text();t.waitUntil(self.registration.showNotification("Notification",{body:i,icon:"/icons/icon-192x192.png"}))}}),self.addEventListener("notificationclick",t=>{t.notification.close(),t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{if(t.length>0){let i=t[0];for(let n=0;n<t.length;n++)if(t[n].focused){i=t[n];break}return i.focus()}return self.clients.openWindow("/notifications")}))});